 CREATE OR REPLACE FUNCTION public.listpetitions(intakenumber character varying, pagenumber bigint, pagesize bigint, sortcolumn character varying, sortorder character varying)                                                                                                        
  RETURNS TABLE(totalcount bigint, intakeservicerequestpetitionid uuid, petitionid character varying, petitiontypekey character varying, createddate timestamp without time zone, petitionstatus character varying, clientactorsid uuid, associatedpetition json, associatedcomplaint json, complaints json)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                     
 AS $function$                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                       
 DECLARE                                                                                                                                                                                                                                                                               
         v_pageoffset int;                                                                                                                                                                                                                                                             
     v_pagenumber int;                                                                                                                                                                                                                                                                 
         v_intakenumber character varying;                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                       
 BEGIN                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                       
         v_pagenumber := pagenumber-1;                                                                                                                                                                                                                                                 
     v_pageoffset = v_pagenumber * pagesize;                                                                                                                                                                                                                                           
         v_intakenumber := intakenumber;                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                       
 RETURN QUERY                                                                                                                                                                                                                                                                          
 select count(1) over(), isrp.intakeservicerequestpetitionid, isrp.petitionid, isrp.petitiontypekey, isrp.insertedon as createddate,isrp.petitionstatustypekey as petitionstatus, isrp.clientactorsid,                                                                                                      
                                                                                                                                                                                                                                                                                       
 (select json_agg(x) from (select associatedpetitionid, (select IIN.petitionid from intakeservicerequestpetition IIN where IIN.intakeservicerequestpetitionid=associatedpetitionid) as associatepetition                                                                               
                         from associatedpetitionsconfig ASPC                                                                                                                                                                                                                           
                         join intakeservicerequestpetition INRP on INRP.intakeservicerequestpetitionid=ASPC.intakeservicerequestpetitionid and INRP.activeflag=1                                                                                                                       
                         where ASPC.activeflag=1 and INRP.intakeservicerequestpetitionid =isrp.intakeservicerequestpetitionid  and associatedevalfieldid is null) as X ) as AssociatedPetition,                                                                                        
                                                                                                                                                                                                                                                                                       
                         (select json_agg(x) from (select associatedevalfieldid, (select IIE.complaintid from intakeservicerequestevaluation IIE where IIE.intakeservicerequestevaluationid=associatedevalfieldid) as associatecomplaint                                               
                         from associatedpetitionsconfig ASPC                                                                                                                                                                                                                           
                         join intakeservicerequestpetition INRP on INRP.intakeservicerequestpetitionid=ASPC.intakeservicerequestpetitionid and INRP.activeflag=1                                                                                                                       
                         where ASPC.activeflag=1 and INRP.intakeservicerequestpetitionid =isrp.intakeservicerequestpetitionid and associatedpetitionid  is null ) as X ) as AssociatedComplaint,                                                                                       
                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                       
 (select json_agg(x) from (                                                                                                                                                                                                                                                            
         select isre.intakeservicerequestevaluationid, isre.complaintid,                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                       
         case when isre.unknownrange=0 then to_char(isre.offensedate,'MM/DD/YYYY')                                                                                                                                                                                                     
  when isre.unknownrange=1 then '' :: character varying                                                                                                                                                                                                                                
   when isre.unknownrange=2 then to_char(isre.begindate,'MM/DD/YYYY')|| ' - ' || to_char(isre.enddate,'MM/DD/YYYY')                                                                                                                                                                    
 end as offensedate ,                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                       
         (select json_agg(x) from (                                                                                                                                                                                                                                                    
                 select p.personid as personid, p.firstname, p.lastname from intakeservreqevalactorconfig isreac                                                                                                                                                                       
                         left join intakeservicerequestactor isra on isra.intakeservicerequestactorid = isreac.intakeservicerequestactorid                                                                                                                                             
                         left join actor ac on isra.actorid = ac.actorid                                                                                                                                                                                                               
                         left join person p on p.personid = ac.personid                                                                                                                                                                                                                
                         where isreac.intakeservicerequestevaluationid = isre.intakeservicerequestevaluationid                                                                                                                                                                         
                         and isreac.activeflag = 1 and isra.activeflag = 1 and ac.activeflag = 1 and p.activeflag = 1                                                                                                                                                                  
                 ) as x) as victims,                                                                                                                                                                                                                                                   
                 (select json_agg(x) from (                                                                                                                                                                                                                                            
                         select a.allegationid, a."name" from intakeservicerequestevaluationconfig isreg                                                                                                                                                                               
                         left join allegation a on a.allegationid = isreg.allegationid                                                                                                                                                                                                 
                         where isreg.intakeservicerequestevaluationid = isre.intakeservicerequestevaluationid                                                                                                                                                                          
                         and isreg.activeflag = 1 and a.activeflag = 1                                                                                                                                                                                                                 
                 ) as x) as offences                                                                                                                                                                                                                                                   
         from intakeservreqevalpetitionconfig isrepc                                                                                                                                                                                                                                   
                 join intakeservicerequestevaluation isre on isre.intakeservicerequestevaluationid = isrepc.intakeservicerequestevaluationid                                                                                                                                           
                 where isrepc.intakeservicerequestpetitionid = isrp.intakeservicerequestpetitionid                                                                                                                                                                                     
                 and isrepc.activeflag = 1 and isre.activeflag = 1                                                                                                                                                                                                                     
 ) as x) as complaints                                                                                                                                                                                                                                                                 
 from intakeservicerequestpetition isrp                                                                                                                                                                                                                                                
 where  isrp.intakenumber = v_intakenumber and isrp.petitionstatustypekey != 'PEFW' and                                                                                                                                                                                                
 isrp.activeflag = 1                                                                                                                                                                                                                                                                   
 ORDER BY                                                                                                                                                                                                                                                                              
         ( CASE sortorder when 'asc' then                                                                                                                                                                                                                                              
                 CASE sortcolumn                                                                                                                                                                                                                                                       
                 when 'createddate' then                                                                                                                                                                                                                                               
           cast( isrp.insertedon as character varying)                                                                                                                                                                                                                                 
                 when 'petitionid' then                                                                                                                                                                                                                                                
           cast( isrp.petitionid as character varying)                                                                                                                                                                                                                                 
                 else cast( isrp.insertedon as character varying) end end) asc,                                                                                                                                                                                                        
         ( CASE sortorder when 'desc' then                                                                                                                                                                                                                                             
                 CASE sortcolumn                                                                                                                                                                                                                                                       
                 when 'createddate' then                                                                                                                                                                                                                                               
           cast( isrp.insertedon as character varying)                                                                                                                                                                                                                                 
                 when 'petitionid' then                                                                                                                                                                                                                                                
           cast( isrp.petitionid as character varying)                                                                                                                                                                                                                                 
                 else cast( isrp.insertedon as character varying) end end) desc                                                                                                                                                                                                        
 LIMIT pagesize OFFSET v_pageoffset;                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                       
 END;                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                       
 $function$                                                                                                                                                                                                                                                                            

